<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>2048</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background: #12151d;
    color: #f5f7fb;
    font-family: Arial, sans-serif;
  }
  .game {
    width: min(92vw, 460px);
  }
  header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 14px;
    margin-bottom: 16px;
  }
  h1 { margin: 0; font-size: 42px; letter-spacing: -2px; }
  .controls { display: flex; gap: 10px; align-items: center; }
  .score-box {
    text-align: center;
    background: #2a3040;
    border-radius: 8px;
    min-width: 92px;
    padding: 7px 12px;
  }
  .score-box small {
    display: block;
    color: #b7c0d4;
    font-size: 10px;
    font-weight: bold;
    letter-spacing: 1px;
  }
  #score { font-size: 22px; font-weight: bold; }
  #reset {
    border: 0;
    border-radius: 8px;
    padding: 12px 14px;
    background: #6175e8;
    color: white;
    font-weight: bold;
    cursor: pointer;
  }
  #reset:hover { background: #788af2; }
  #board {
    aspect-ratio: 1;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
    padding: 10px;
    background: #272d3b;
    border-radius: 12px;
    box-shadow: 0 12px 35px #0007;
  }
  .cell {
    display: grid;
    place-items: center;
    min-width: 0;
    border-radius: 7px;
    background: #353d4e;
    color: #f8f9ff;
    font-size: clamp(21px, 7vw, 38px);
    font-weight: 800;
  }
  .cell[data-value="0"] { color: transparent; }
  .cell[data-value="2"] { background: #54627c; }
  .cell[data-value="4"] { background: #496d8c; }
  .cell[data-value="8"] { background: #386f8b; }
  .cell[data-value="16"] { background: #347c87; }
  .cell[data-value="32"] { background: #438749; }
  .cell[data-value="64"] { background: #8a7440; }
  .cell[data-value="128"] { background: #98713c; }
  .cell[data-value="256"] { background: #9c5937; }
  .cell[data-value="512"] { background: #984446; }
  .cell[data-value="1024"] { background: #81477f; font-size: clamp(17px, 5.5vw, 30px); }
  .cell[data-value="2048"] { background: #704bc0; font-size: clamp(17px, 5.5vw, 30px); }
  .cell[data-value="4096"],
  .cell[data-value="8192"] { background: #d5a92f; font-size: clamp(15px, 5vw, 27px); }
  p { color: #aeb8cb; text-align: center; margin: 14px 0 0; font-size: 14px; }
</style>
</head>
<body>
  <main class="game">
    <header>
      <h1>2048</h1>
      <div class="controls">
        <div class="score-box"><small>SCORE</small><span id="score">0</span></div>
        <button id="reset" type="button">New Game</button>
      </div>
    </header>
    <div id="board" aria-label="2048 game board"></div>
    <p>Use arrow keys to move tiles.</p>
  </main>

<script>
(() => {
  const size = 4;
  let grid = [];
  let currentScore = 0;

  const boardElement = document.getElementById('board');
  const scoreElement = document.getElementById('score');

  function render() {
    boardElement.innerHTML = '';
    for (let row = 0; row < size; row++) {
      for (let col = 0; col < size; col++) {
        const value = grid[row][col];
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.value = value;
        cell.textContent = value || '';
        boardElement.appendChild(cell);
      }
    }
    scoreElement.textContent = currentScore;
  }

  function emptyCells() {
    const cells = [];
    for (let row = 0; row < size; row++) {
      for (let col = 0; col < size; col++) {
        if (grid[row][col] === 0) cells.push([row, col]);
      }
    }
    return cells;
  }

  function spawnTile() {
    const cells = emptyCells();
    if (!cells.length) return;
    const [row, col] = cells[Math.floor(Math.random() * cells.length)];
    grid[row][col] = Math.random() < 0.1 ? 4 : 2;
  }

  function collapse(line) {
    const values = line.filter(value => value !== 0);
    const result = [];
    for (let i = 0; i < values.length; i++) {
      if (values[i] === values[i + 1]) {
        const merged = values[i] * 2;
        result.push(merged);
        currentScore += merged;
        i++;
      } else {
        result.push(values[i]);
      }
    }
    while (result.length < size) result.push(0);
    return result;
  }

  function move(direction) {
    let changed = false;

    for (let index = 0; index < size; index++) {
      let line;
      if (direction === 'left' || direction === 'right') {
        line = grid[index].slice();
      } else {
        line = grid.map(row => row[index]);
      }

      if (direction === 'right' || direction === 'down') line.reverse();
      const collapsed = collapse(line);
      if (direction === 'right' || direction === 'down') collapsed.reverse();

      if (line.some((value, i) => value !== collapsed[i])) changed = true;

      if (direction === 'left' || direction === 'right') {
        grid[index] = collapsed;
      } else {
        for (let row = 0; row < size; row++) grid[row][index] = collapsed[row];
      }
    }

    if (changed) spawnTile();
    render();
    return changed;
  }

  function reset() {
    grid = Array.from({ length: size }, () => Array(size).fill(0));
    currentScore = 0;
    spawnTile();
    spawnTile();
    render();
  }

  function setBoard(arr) {
    if (!Array.isArray(arr) || arr.length !== size ||
        arr.some(row => !Array.isArray(row) || row.length !== size)) {
      throw new Error('Board must be a 4x4 array.');
    }
    grid = arr.map(row => row.map(value => Number(value) || 0));
    render();
  }

  window.game = {
    size,
    reset,
    move,
    board: () => grid.map(row => row.slice()),
    setBoard,
    score: () => currentScore
  };

  document.getElementById('reset').addEventListener('click', reset);
  document.addEventListener('keydown', event => {
    const directions = {
      ArrowLeft: 'left',
      ArrowRight: 'right',
      ArrowUp: 'up',
      ArrowDown: 'down'
    };
    if (directions[event.key]) {
      event.preventDefault();
      move(directions[event.key]);
    }
  });

  reset();
})();
</script>
</body>
</html>
